import{_ as o,o as i,c as a,a2 as n}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0041 — Control plane del cloud: ruoli, identità, eliminazione degli account, rubrica e notifiche","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0041-control-plane-ruoli-identita-account.md","filePath":"adr/0041-control-plane-ruoli-identita-account.md"}'),t={name:"adr/0041-control-plane-ruoli-identita-account.md"};function r(c,e,l,d,s,u){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0041-—-control-plane-del-cloud-ruoli-identita-eliminazione-degli-account-rubrica-e-notifiche" tabindex="-1">ADR-0041 — Control plane del cloud: ruoli, identità, eliminazione degli account, rubrica e notifiche <a class="header-anchor" href="#adr-0041-—-control-plane-del-cloud-ruoli-identita-eliminazione-degli-account-rubrica-e-notifiche" aria-label="Permalink to &quot;ADR-0041 — Control plane del cloud: ruoli, identità, eliminazione degli account, rubrica e notifiche&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Data</strong></td><td>2026-11-01</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§1.3 (stato utente, cache 30 s), §2.6.4–2.6.5 (condivisione, gruppi), §3.3 (ruoli e permessi), §3.5.1 (<code>/me</code>, <code>/directory/*</code>), §3.5.4 (<code>POST /shares</code>), §3.6 (notifiche); D-05; ADR-0021, ADR-0033</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no per i punti 1–7 e 10; i punti 8 e 9 sono interpretazioni di §3.5.4 e §2.6.5, che lo spec lascia ambigue e che vanno recepite; il punto 5 modifica ADR-0021 (grant concessi), non lo spec</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La revisione W8 (<code>.dev/w8-findings.md</code>, lotto A2) ha trovato nel control plane del cloud (auth, utenti, amministrazione, privacy, notifiche) comportamenti corretti nel caso comune ma fragili ai bordi:</p><ul><li>un cambio di ruolo fatto dalla console veniva annullato dalla richiesta successiva che portava un token emesso prima del cambio (il provisioning riscriveva il ruolo dai realm role del token);</li><li>un token con un&#39;e-mail già usata da un altro account vivo produceva <code>500 INTERNAL</code> a ogni richiesta;</li><li>il provisioning scriveva la riga <code>users</code> a ogni scadenza della cache (30 s per utente e per replica), e per gli account sospesi a ogni richiesta;</li><li>il controllo &quot;ultimo amministratore&quot; di sospensione, degradazione ed eliminazione era un <code>COUNT</code> senza lock, e l&#39;eliminazione dalla console divergeva dalla cancellazione dell&#39;account (ADR-0021);</li><li>la cancellazione di un account cancellava in silenzio i grant che l&#39;utente aveva concesso come <em>manager</em> su vault di altri;</li><li>la rubrica cercava le e-mail per sottostringa, permettendo di indovinare indirizzi un pezzo alla volta;</li><li><code>/me</code> riportava <code>config_version</code> sempre 0; <code>POST /shares</code> e il ruolo <code>manager</code> dei gruppi non seguivano lo spec;</li><li>l&#39;hub delle notifiche perdeva gli eventi emessi mentre la connessione <code>LISTEN</code> era caduta, interrogava il database per ogni NOTIFY nella goroutine del listener e non limitava gli stream per utente.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><p><strong>Il ruolo del database prevale sui token emessi prima di un cambio fatto dalla console.</strong> Nuova colonna <code>users.role_changed_at</code> (migrazione <code>0008_role_changed_at.sql</code>), impostata da <code>SetUserRole</code>. Il provisioning prende il ruolo dal token solo se il suo <code>iat</code> è successivo a <code>role_changed_at</code> (<code>users.EffectiveRole</code>, stessa regola in SQL in <code>UpsertUserFromToken</code>); il <code>Principal</code> usa sempre il ruolo della riga. Una degradazione vale dalla richiesta successiva (subito sulla replica che la esegue grazie a <code>Invalidate</code>, entro <code>OIDC_STATUS_CACHE_TTL</code> sulle altre), una promozione non attende un nuovo token, e i token emessi dopo il cambio tornano a rispecchiare Keycloak, che resta la fonte del ruolo per chi lo gestisce lì. <code>iat</code> ha la precisione del secondo: un token del secondo del cambio conta come precedente, il che è innocuo perché il ruolo salvato è già quello nuovo. Il cambio di ruolo dalla console ora <strong>richiede</strong> l&#39;Admin API di Keycloak: con <code>ErrDisabled</code> risponde <code>INVALID_STATE</code> invece di applicare un ruolo che il token successivo annullerebbe (resta tollerato <code>ErrNotFound</code>, account non più in Keycloak).</p></li><li><p><strong>Conflitto di identità: errore esplicito, nessun ricollegamento per e-mail.</strong> Una violazione di unicità sull&#39;e-mail durante il provisioning diventa <code>auth.ErrIdentityConflict</code>, mappato su <code>409 INVALID_STATE</code> (HTTP) e <code>FAILED_PRECONDITION</code> (gRPC) con un messaggio che indica di rivolgersi a un amministratore; non si crea né si modifica alcuna riga. Il collegamento resta solo per <code>sub</code>: ricollegare per e-mail darebbe i vault di un account a chiunque controlli quell&#39;indirizzo nel provider di identità. Il rimedio (eliminare o rinominare l&#39;account precedente) è nel runbook. Non si introduce un nuovo codice di errore (richiederebbe di toccare <code>syncproto</code> e il contratto): <code>INVALID_STATE</code> con <code>detail</code> è sufficiente e già gestito dai client. <code>admin.UpdateUser</code> aggiorna prima il database e chiama Keycloak dentro la stessa transazione, così un&#39;e-mail duplicata fallisce prima di toccare Keycloak e un errore di Keycloak annulla la modifica.</p></li><li><p><strong>Provisioning in lettura.</strong> <code>Provision</code> legge la riga per <code>sub</code> e scrive solo se il token porta un cambio di profilo o di ruolo, o se <code>last_login_at</code> è più vecchio di 15 minuti. Gli account sospesi o eliminati non vengono mai scritti (e <code>UpsertUserFromToken</code> non aggiorna <code>last_login_at</code> di un account sospeso). La cache del middleware memorizza anche i rifiuti (<code>ErrSuspended</code>, <code>ErrIdentityConflict</code>) per lo stesso TTL; <code>Invalidate</code> (attivazione, cambio di ruolo, eliminazione) li rimuove. Gli errori interni non sono memorizzati. La cache elimina le voci scadute quando supera 4096 soggetti.</p></li><li><p><strong>Un solo percorso per togliere un amministratore, con lock.</strong> Sospensione, degradazione ed eliminazione prendono il lock di tutte le righe degli amministratori attivi (<code>users.LockActiveAdmins</code>, <code>SELECT … FOR UPDATE</code> in ordine di id), rileggono il bersaglio e decidono sul conteggio sotto lock: due amministratori che si rimuovono a vicenda non possono più lasciare il servizio senza amministratori. L&#39;eliminazione dalla console usa la stessa funzione della cancellazione dell&#39;account (<code>privacy.DeleteAccount</code>): anonimizzazione immediata, vault in conservazione, rimozione di appartenenze, grant ricevuti, upload ed export pronti. <strong>Ordine dei lock:</strong> prima le righe dei vault dell&#39;account (<code>vaults.LockVault</code>, in ordine di id), poi le righe utente, come fa un commit (vault, poi uso del proprietario), per non andare in deadlock con un commit in un vault dell&#39;account.</p></li><li><p><strong>I grant concessi da un manager che cancella l&#39;account restano validi.</strong> ADR-0021 cancellava i grant &quot;concessi&quot; dall&#39;utente; ma <code>granted_by</code> passa al manager anche quando modifica il livello di un grant creato dal proprietario, e la cancellazione toglieva l&#39;accesso a terzi su vault di altri senza avvisare nessuno. Ora i grant concessi su vault di <strong>altri</strong> proprietari sono riattribuiti al proprietario del vault (<code>ReattributeForeignGrants</code>); per ogni condivisione toccata si registra l&#39;audit <code>share.grants_reattributed</code> e si notifica <code>ShareChanged{kind: updated}</code>. I grant sui vault dell&#39;account stesso sono cancellati come prima (quei vault entrano in conservazione). Lo spec non dice nulla di diverso (§2.6.4 non tratta l&#39;eliminazione di un manager); va aggiornato ADR-0021.</p></li><li><p><strong>Rubrica (<code>GET /directory/users</code>).</strong> Username e nome visualizzato si cercano per sottostringa (con <code>%</code> e <code>_</code> trattati come caratteri letterali); l&#39;e-mail solo per <strong>corrispondenza esatta</strong>, senza distinzione di maiuscole. Chi conosce l&#39;indirizzo può ancora invitare per e-mail (e quindi confermare che l&#39;indirizzo ha un account: è il prezzo dell&#39;invito per e-mail, comune a ogni sistema di condivisione), ma non si può più ricostruire un indirizzo per tentativi né elencare gli utenti di un dominio. La risposta continua a non contenere l&#39;e-mail (&quot;campi minimi&quot;, §3.5.1). Anche la ricerca dei gruppi tratta i caratteri jolly come letterali.</p></li><li><p><strong><code>/me.config_version</code></strong> è la revisione di configurazione (<code>settings</code> <code>config.revision</code>), la stessa che porta <code>ConfigChanged.version</code> e <code>EffectiveConfig.version</code> (§3.6): un client la confronta con quella che ha per sapere se rileggere <code>/config/effective</code>.</p></li><li><p><strong><code>POST /shares</code> da parte di un manager (§3.5.4 &quot;U (owner/manager)&quot;) — accettata e implementata (vedi «Esito»).</strong> Lo spec non dice <em>manager di cosa</em>. Interpretazione proposta: può creare uno share chi ha un grant <code>manager</code> <strong>accettato</strong> su uno share attivo (non revocato né scaduto) dello stesso vault, purché l&#39;ambito del nuovo share sia contenuto in quello dello share che gestisce (vault ⊇ cartella con prefisso ⊇ file) e i grant iniziali non superino <code>manager</code>; <code>created_by</code> è il manager, la revoca dello share e l&#39;eliminazione del vault restano al solo proprietario (tabella dei permessi di §3.3). Senza il vincolo di contenimento un manager di una cartella potrebbe condividere l&#39;intero vault. L&#39;implementazione sta nel modulo <code>sharing</code> (lotto data plane).</p></li><li><p><strong>Ruolo <code>manager</code> nei gruppi (§2.6.5) — riservato in v1 (confermato).</strong> Lo spec lo elenca ma non gli attribuisce alcuna capacità: gruppi e membri si gestiscono solo da <code>/admin/groups</code> (§3.5.5, D-05). In v1 il ruolo è memorizzato e mostrato ma <strong>non ha effetti di autorizzazione</strong>. Un&#39;estensione naturale per una versione successiva è permettere al manager di gestire i membri del proprio gruppo; va decisa nello spec.</p></li><li><p><strong>Notifiche.</strong></p><ul><li>Il listener non interroga più il database: accoda gli eventi dei vault (coalescendoli per vault) e quelli delle condivisioni (coda limitata a 10 000; oltre, si svuota e si chiede un riallineamento) per un dispatcher che risolve proprietari e lettori di un intero lotto con due query (<code>GetVaultOwners</code>, <code>ListVaultsRecipients</code>). Gli iscritti sono indicizzati per utente; le cache hanno TTL e vengono ripulite ogni minuto; un evento di condivisione invalida solo il vault dello share.</li><li>Dopo una caduta della connessione <code>LISTEN</code>, una volta di nuovo in ascolto l&#39;hub <strong>riallinea</strong> ogni iscritto dal database (<code>Hub.Resync</code>): vault e revisione di configurazione più avanti di quanto l&#39;iscritto conosce (posizioni inviate dal client alla connessione e quelle spedite dopo) e, per gli account sospesi o eliminati nel frattempo, l&#39;evento di sospensione che chiude lo stream. Gli eventi di condivisione non sono ricostruibili: un vault condiviso nel frattempo compare come evento di vault, uno revocato risponde <code>NOT_FOUND</code> al pull successivo. Non serve un nuovo tipo di evento né modifiche ai client.</li><li>Al massimo 32 stream per utente e per replica (<code>RESOURCE_EXHAUSTED</code> su gRPC, <code>429 RATE_LIMITED</code> su SSE). Ogni scrittura SSE ha una deadline di 30 s. gRPC: interceptor di recovery dei panic, <code>MaxConnectionAge</code> 30 minuti con 1 minuto di grazia (riequilibrio tra repliche e limite al tempo in cui un client che non legge tiene un <code>Send</code> bloccato), spegnimento che chiude prima gli stream (<code>UNAVAILABLE</code>) e poi attende <code>GracefulStop</code> entro <code>SHUTDOWN_TIMEOUT</code>.</li><li>Il protocollo <code>vault_changed</code> (canale e payload) è definito una volta in <code>notify</code> (<code>Channel</code>, <code>FormatMessage</code>, <code>PublishVaultChanged</code>); un test verifica che <code>sync</code> pubblichi sullo stesso canale finché non chiama <code>notify.PublishVaultChanged</code>.</li></ul></li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Ruolo = minimo tra token e database.</strong> Scartata: risolve la degradazione ma non la promozione, e non distingue un cambio fatto in Keycloak dopo quello della console.</li><li><strong>Ruolo sempre dal database, ignorando i realm role dopo il primo accesso.</strong> Scartata: un ruolo assegnato direttamente in Keycloak (procedura documentata in <code>keycloak.md</code>) non avrebbe più effetto.</li><li><strong>Logout forzato in Keycloak alla degradazione.</strong> Non basta da solo: l&#39;access token già emesso resta valido fino alla scadenza; resta possibile come aggiunta.</li><li><strong>Ricollegare l&#39;account per e-mail quando il vecchio <code>sub</code> non esiste più in Keycloak.</strong> Scartata: richiede una chiamata all&#39;Admin API nel percorso di autenticazione e apre la presa di possesso di un account tramite il provider di identità.</li><li><strong>Rimuovere l&#39;e-mail dalla ricerca della rubrica.</strong> Scartata: impedirebbe l&#39;invito per e-mail, il caso più comune.</li><li><strong>Evento <code>resync</code> esplicito nel protocollo delle notifiche.</strong> Scartato per ora: richiede di modificare proto, OpenAPI e client; il riallineamento con eventi esistenti ottiene lo stesso effetto per vault, configurazione e sospensioni.</li><li><strong>Pool di worker per le risoluzioni del dispatcher.</strong> Non necessario: la risoluzione per lotti riduce le query a due per lotto, e la coalescenza per vault limita la memoria al numero di vault attivi.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Migrazione additiva <code>0008</code> (compatibile con il rolling update: le repliche vecchie ignorano la colonna; finché girano, un loro provisioning può ancora riscrivere il ruolo da un token vecchio).</li><li>L&#39;eliminazione dalla console anonimizza subito: il nome dell&#39;utente eliminato non compare più nel dettaglio dell&#39;audit successivo; il job di purge resta idempotente e completa gli account eliminati prima di questa modifica.</li><li>Il cambio di ruolo dalla console fallisce se l&#39;Admin API di Keycloak non è configurata (prima riusciva solo in apparenza).</li><li>Da fare fuori da questo lotto: <code>sync</code> deve pubblicare con <code>notify.PublishVaultChanged</code> (anche in <code>restore.go</code>); recepire i punti 5, 8 e 9 nello spec (§2.6.4, §2.6.5, §3.5.4) e aggiornare ADR-0021.</li></ul><h2 id="esito" tabindex="-1">Esito <a class="header-anchor" href="#esito" aria-label="Permalink to &quot;Esito&quot;">​</a></h2><p>Il proprietario ha accettato il punto 8 come proposto e confermato il punto 9 (2026-11-02).</p><p><strong>Punto 8 — creazione di share da parte di un manager.</strong></p><ul><li><strong>Chi può creare.</strong> <code>POST /shares</code> accetta il proprietario del vault (come prima) oppure un utente che ha un grant <code>manager</code> <strong>accettato</strong>, diretto o tramite un gruppo, su uno share <strong>attivo</strong> (non revocato, non scaduto) dello stesso vault (query <code>ListManagedSharesOfVault</code> in <code>internal/db/queries/sharing.sql</code>). Un grant in attesa, un grant <code>editor</code>/<code>viewer</code>, uno share revocato o scaduto non danno nulla: per chi non è né proprietario né manager il vault resta invisibile (<code>404 NOT_FOUND</code>, come prima).</li><li><strong>Contenimento.</strong> L&#39;ambito del nuovo share deve stare dentro quello di almeno uno degli share gestiti (<code>access.Scope.ContainsScope</code>): sotto uno share di vault va bene tutto (anche l&#39;intero vault); sotto uno share di cartella la cartella stessa, una sua sottocartella o un documento sotto di essa, con i percorsi confrontati come <code>path_key</code> (NFC, senza distinzione di maiuscole, per segmenti: <code>Progetti/Alfabeto</code> non è dentro <code>Progetti/Alfa</code>); sotto uno share di documento solo lo stesso documento (<code>file_id</code>). Fuori da ogni share gestito la risposta è <code>403 FORBIDDEN</code> (il vault esiste per il chiamante, l&#39;ambito no); un percorso non valido resta <code>400 PATH_INVALID</code>, una cartella vuota <code>404</code>.</li><li><strong>Grant iniziali.</strong> Al massimo <code>manager</code>, come per chiunque (<code>putGrant</code>): <code>owner</code> non è un livello concedibile e il proprietario non può essere destinatario.</li><li><strong>Titolarità.</strong> Lo share appartiene al vault: <code>shares.created_by</code> è il manager, l&#39;audit <code>share.create</code> ha come attore il manager e nel dettaglio <code>via_share</code> (lo share gestito che lo contiene). Il proprietario lo vede, lo modifica e lo revoca come ogni altro share.</li><li><strong>Gestione.</strong> Il manager che l&#39;ha creato lo gestisce (nome, scadenza, grant) <strong>finché</strong> ha ancora un grant <code>manager</code> accettato su un altro share attivo dello stesso vault che lo contiene (<code>creatorManages</code> in <code>internal/sharing/delegate.go</code>); lo vede in <code>GET /shares?scope=owned</code> con <code>my_permission: manager</code>, <code>my_status: accepted</code>. La <strong>revoca</strong> resta al solo proprietario (tabella dei permessi di §3.3).</li><li><strong>Revoca o scadenza del grant del manager.</strong> Lo spec e la proposta non ne parlavano; si è scelto di <strong>non</strong> toccare gli share derivati: restano attivi con i loro grant (nessuna perdita di accesso per i destinatari, coerente con il punto 5), il manager smette di vederli e gestirli, il proprietario continua a gestirli e può revocarli.</li><li><strong>Vault privati.</strong> Non hanno share (D-02), quindi nessuno ne è manager: per un non proprietario sono <code>404</code>, per il proprietario resta <code>409 VAULT_ENCRYPTED</code>.</li><li><strong>File.</strong> Server: <code>internal/access/access.go</code> (<code>ContainsScope</code>), <code>internal/sharing/delegate.go</code>, <code>internal/sharing/service.go</code> (<code>Create</code>, <code>view</code>, <code>buildView</code>, <code>views</code>), <code>internal/db/queries/sharing.sql</code> (<code>ListManagedSharesOfVault</code>, <code>ListManagedSharesOfUser</code>, <code>ListSharesOfVaultOwner</code> esteso a <code>created_by</code>); contratto: descrizione di <code>createShare</code> e risposta <code>403</code> in <code>api/openapi.yaml</code>. Client: <code>SharingAPI.CreateCloudShare</code> (<code>apps/desktop/internal/sync/manager_share.go</code>) non controlla più la proprietà: un vault che non è dell&#39;utente (<code>GET /vaults/{id}</code> → 404) passa al server, un vault proprio privato è ancora rifiutato in locale; in <code>@memobrain/cloud-features</code> <code>SharesManager</code> offre «Condividi una parte» sulle condivisioni di vault o cartella che l&#39;utente gestisce (non possiede) e <code>NewShareInsideDialog</code> permette di scegliere solo dentro di esse (l&#39;intero vault o una cartella; l&#39;intera cartella o una sottocartella), in console, nelle impostazioni del desktop e nel workbench.</li><li><strong>Test.</strong> <code>services/cloud/test/integration/sharing_manager_test.go</code> (dentro/fuori ambito, maiuscole, documento, grant oltre <code>manager</code>, grant in attesa, grant tramite gruppo, revoca e scadenza, vault privato, proprietario), <code>internal/access/access_test.go</code>, <code>internal/sharing/view_test.go</code>, <code>apps/desktop/internal/sync/manager_share_test.go</code>, suite dei componenti su entrambi gli adattatori (<code>accountSuite.tsx</code>), e2e <code>web/e2e/shares.spec.ts</code> e <code>apps/desktop/frontend/e2e/account-panels.spec.ts</code>.</li><li><strong>Limiti.</strong> La UI non offre la ricondivisione di uno share di documento (lato server è supportata) né il menu «Condividi…» dell&#39;esplorazione dentro un mount: il percorso è da Impostazioni → Condivisione / pagina Condivisioni.</li></ul><p><strong>Punto 9 — ruolo <code>manager</code> nei gruppi.</strong> Confermato riservato in v1: memorizzato e mostrato, senza effetti di autorizzazione. Nessuna query lo usa in una condizione (<code>internal/db/reserved_role_test.go</code> lo verifica sulle query, <code>TestGroupManagerRoleGrantsNothing</code> sul comportamento: niente gestione di share, niente creazione, niente <code>/admin/groups</code>, niente scrittura con un grant <code>viewer</code> del gruppo). La console (dettaglio del gruppo) e «I miei gruppi» avvisano che il ruolo non dà permessi in più.</p>',16)])])}const m=o(t,[["render",r]]);export{g as __pageData,m as default};
